input.content:
:root {
  color-scheme: light dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

body {
  margin: 0;
  background: light-dark(#f7f7f5, #16181c);
  color: light-dark(#1a1a1a, #eaeaea);
}

#app {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
}

#note-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid light-dark(#d8d8d4, #333);
  border-radius: 8px;
  margin-bottom: 1.5rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem;
  border: 1px solid light-dark(#c4c4be, #444);
  border-radius: 6px;
  background: light-dark(#fff, #1f2126);
  color: inherit;
}

.hint {
  margin: 0;
  font-size: 0.75rem;
  opacity: 0.7;
}

button {
  font: inherit;
  cursor: pointer;
}

#note-form button[type="submit"] {
  align-self: flex-start;
  padding: 0.5rem 1.25rem;
  border: none;
  border-radius: 6px;
  background: #0f766e;
  color: #fff;
}

.search-bar {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

#results-line {
  margin: 0;
  font-size: 0.85rem;
  opacity: 0.75;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 0.75rem;
  padding: 1rem;
  border: 1px solid light-dark(#d8d8d4, #333);
  border-radius: 8px;
}

.note[aria-current="true"] {
  outline: 2px solid #0f766e;
  outline-offset: 2px;
}

.note-avatar {
  grid-row: 1 / 3;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
}

.note-title {
  grid-column: 2;
  display: block;
  text-align: left;
  background: none;
  border: none;
  padding: 0;
  font-size: 1.1rem;
  font-weight: 700;
  color: inherit;
}

.note-title:hover,
.note-title:focus-visible {
  text-decoration: underline;
}

.note-body {
  grid-column: 2;
  line-height: 1.5;
  word-wrap: break-word;
}

.note-body a {
  color: #0f766e;
}

*:focus-visible {
  outline: 2px solid #0f766e;
  outline-offset: 2px;
}

